import {cashChange} from './bank.js';
import {advanceLife} from './life.js';
import {activeMeals,heldMeal,newMeal} from './home-life.js';
export const DESTINATION_IDS=['island-house','club','beach','islandfood'];
export const DESTINATION_STATIONS={ 'island-house':{desk:{x:2.5,z:-1.55},bed:{x:-2.1,z:.1}},club:{dance:{x:0,z:-.6}},beach:{bin:{x:-3,z:1.8},litter0:{x:-2.8,z:-1.6},litter1:{x:2.4,z:-2.2},litter2:{x:2.8,z:1.3}},islandfood:{counter:{x:2.5,z:-1.55}}};
const yes=message=>({ok:true,message}),no=message=>({ok:false,message});
export function atDestination(view,p,id,station){const target=DESTINATION_STATIONS[id]?.[station];return view===id&&target&&Math.hypot(p.x-target.x,p.z-target.z)<1.15;}
export function migrateDestinations(s,data){s.cityVisits=data?.cityVisits?structuredClone(data.cityVisits):{version:1,hotelSerial:0,mealSerial:0,clubSerial:0,hotel:null,club:null,beach:{day:s.day,collected:[],deposited:false},stats:{rested:0,danced:0,cleaned:0,takeaways:0}};}
export function validDestinations(c){if(c===undefined)return true;const int=n=>Number.isSafeInteger(n)&&n>=0&&n<=1e9;if(!c||c.version!==1||!['hotelSerial','mealSerial','clubSerial'].every(k=>int(c[k]))||!c.stats||!['rested','danced','cleaned','takeaways'].every(k=>int(c.stats[k])))return false;const h=c.hotel,b=c.beach,d=c.club;return (h===null||h&&int(h.id)&&h.id>0&&h.id<=c.hotelSerial&&['booked','used','cancelled'].includes(h.status))&&b&&int(b.day)&&typeof b.deposited==='boolean'&&Array.isArray(b.collected)&&b.collected.length<=3&&new Set(b.collected).size===b.collected.length&&b.collected.every(n=>[0,1,2].includes(n))&&(d===null||d&&int(d.id)&&d.id>0&&d.id<=c.clubSerial&&int(d.hits)&&d.hits<=4&&Number.isInteger(d.lastBeat)&&d.lastBeat>=-1&&Number.isFinite(d.elapsed)&&d.elapsed>=0&&d.elapsed<=180&&int(d.rewardDay)&&typeof d.finished==='boolean');}
export function bookHotel(s,serial,view,p){const c=s.cityVisits;if(c.hotelSerial>=1e9)return no('Booking limit reached.');if(!atDestination(view,p,'island-house','desk')||serial!==c.hotelSerial||c.hotel?.status==='booked')return no('Approach reception; an existing booking can be used or cancelled.');if(s.money<700)return no('This rest booking costs ₦700 game currency.');cashChange(s,-700,'purchase',{sku:'hotel',ref:'hotel-'+(c.hotelSerial+1)});c.hotel={id:++c.hotelSerial,status:'booked'};return yes('Rest room booked. Walk to the bed; unused bookings can be refunded at reception.');}
export function cancelHotel(s,id,view,p){const h=s.cityVisits.hotel;if(!atDestination(view,p,'island-house','desk')||h?.id!==id||h.status!=='booked')return no('This booking cannot be refunded.');h.status='cancelled';cashChange(s,700,'refund',{ref:'hotel-'+id});return yes('Unused booking refunded once.');}
export function restHotel(s,id,view,p){const h=s.cityVisits.hotel;if(!atDestination(view,p,'island-house','bed')||h?.id!==id||h.status!=='booked')return no('Book at reception, then approach the bed.');h.status='used';advanceLife(s,120);s.energy=Math.min(100,s.energy+45);s.mood=Math.min(100,s.mood+10);s.cityVisits.stats.rested++;return yes('Two game hours rested. Booking used.');}
export function buyTakeaway(s,serial,view,p){const c=s.cityVisits;if(c.mealSerial>=1e9||s.daily.cookSerial>=1e9)return no('Meal limit reached.');if(!atDestination(view,p,'islandfood','counter')||serial!==c.mealSerial)return no('Approach Lagoon Pot’s counter.');if(heldMeal(s)||activeMeals(s).length>=20)return no('Free your hand and meal storage first.');if(s.money<700)return no('Pepper yam takeaway costs ₦700 game currency.');const id='cook-'+(s.daily.cookSerial+1);if(!newMeal(s,id,'pepper-yam',{carry:true}))return no('Meal already handled.');s.daily.cookSerial++;c.mealSerial++;cashChange(s,-700,'purchase',{sku:'takeaway',ref:'takeaway-'+c.mealSerial});c.stats.takeaways++;return yes('Pepper yam is in your hand. Carry it home to eat or store.');}
export function startDance(s,serial,view,p){const c=s.cityVisits;if(c.clubSerial>=1e9)return no('Session limit reached.');if(!atDestination(view,p,'club','dance')||serial!==c.clubSerial)return no('Approach the dance floor.');if(c.club&&!c.club.finished&&c.club.elapsed<180)return yes('Dance resumed. Tap on the green beat.');const day=c.club?.rewardDay||0;c.club={id:++c.clubSerial,hits:0,lastBeat:-1,elapsed:0,rewardDay:day,finished:false};return yes('Free dance session. Land four different green beats. Mood reward at most once per game day.');}
export function danceTick(s,dt){const d=s.cityVisits.club;if(d&&!d.finished)d.elapsed=Math.min(180,d.elapsed+Math.max(0,Math.min(.05,dt)));}
export function danceBeat(s,id,beat,view,p){const d=s.cityVisits.club;if(!atDestination(view,p,'club','dance')||!d||d.id!==id||d.finished||beat!==Math.floor(d.elapsed)||beat===d.lastBeat)return no('That beat is already handled.');const phase=d.elapsed%1;if(phase<.25||phase>.7)return no('Wait for green, then tap.');d.lastBeat=beat;d.hits++;if(d.hits===4){d.finished=true;s.cityVisits.stats.danced++;if(d.rewardDay!==s.day){s.mood=Math.min(100,s.mood+15);d.rewardDay=s.day;}return yes('Four beats landed. Session complete.');}return yes(d.hits+'/4 beats landed.');}
export function collectBeach(s,index,view,p){const b=s.cityVisits.beach;if(!atDestination(view,p,'beach','litter'+index)||![0,1,2].includes(index))return no('Approach the visible litter.');if(b.deposited&&b.day!==s.day){b.collected=[];b.deposited=false;b.day=s.day;}if(b.deposited||b.collected.includes(index))return no('Already collected.');b.collected.push(index);return yes('Picked up '+b.collected.length+'/3. Take the bag to the recycling bin.');}
export function depositBeach(s,view,p){const b=s.cityVisits.beach;if(!atDestination(view,p,'beach','bin')||b.deposited||b.collected.length!==3)return no('Collect all three pieces before using the bin.');b.deposited=true;s.cityVisits.stats.cleaned++;s.mood=Math.min(100,s.mood+15);s.energy=Math.max(0,s.energy-2);return yes('Beach clean-up complete. Once per game day; no cash charge.');}
